(function () {
'use strict';
var canvas = document.querySelector('[data-aurora]');
var saveData = navigator.connection && navigator.connection.saveData;
if (!canvas || saveData) {
return;
}
var panel = canvas.parentElement;
var VERTEX = 'attribute vec2 position; void main() { gl_Position = vec4(position, 0.0, 1.0); }';
var FRAGMENT = `
precision highp float;
uniform vec2 u_res;
uniform vec2 u_pointer;
uniform float u_time;
const vec3 COLOR_0 = vec3(0.024, 0.082, 0.204);
const vec3 COLOR_1 = vec3(0.051, 0.149, 0.333);
const vec3 COLOR_2 = vec3(0.043, 0.384, 0.706);
const vec3 COLOR_3 = vec3(0.0, 0.702, 0.965);
const vec3 COLOR_4 = vec3(0.851, 0.965, 1.0);
float hash(vec2 p) {
return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}
float valueNoise(vec2 p) {
vec2 i = floor(p);
vec2 f = fract(p);
vec2 u = f * f * (3.0 - 2.0 * f);
float a = hash(i);
float b = hash(i + vec2(1.0, 0.0));
float c = hash(i + vec2(0.0, 1.0));
float d = hash(i + vec2(1.0, 1.0));
return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}
mat2 rotate2d(float angle) {
float s = sin(angle);
float c = cos(angle);
return mat2(c, -s, s, c);
}
float fbm(vec2 p) {
float value = 0.0;
float amplitude = 0.52;
mat2 turn = mat2(0.84, 0.54, -0.54, 0.84);
for (int i = 0; i < 5; i++) {
value += amplitude * valueNoise(p);
p = turn * p * 2.03 + 0.17;
amplitude *= 0.5;
}
return value;
}
void main() {
vec2 uv = gl_FragCoord.xy / u_res;
float aspect = u_res.x / max(u_res.y, 1.0);
vec2 p = (uv - 0.5) * vec2(aspect, 1.0);
float t = u_time * 0.075;
vec2 direction = vec2(0.951, -0.309);
vec2 crossDirection = vec2(-direction.y, direction.x);
vec2 pointer = (u_pointer - 0.5) * vec2(aspect, 1.0);
vec2 pointerDelta = pointer - p;
float pointerFalloff = smoothstep(0.68, 0.0, length(pointerDelta));
p += crossDirection * pointerDelta.x * pointerFalloff * 0.035 * 0.7;
p += direction * pointerDelta.y * pointerFalloff * 0.022 * 0.7;
float warpA = fbm(p * 0.82 + direction * t * 0.71 + vec2(2.7, -1.3));
float warpB = fbm(rotate2d(0.73) * p * 1.08 - crossDirection * t * 0.53 + vec2(-4.1, 3.6));
float warpC = fbm(rotate2d(-0.46) * p * 1.42 + vec2(-t * 0.31, t * 0.43) + 8.2);
vec2 silk = p;
silk += vec2(warpA - 0.5, warpB - 0.5) * 0.72;
silk += direction * (warpC - 0.5) * 0.28;
float fieldA = fbm(rotate2d(0.28) * silk * 0.74 + direction * t * 0.83 + 1.9);
float fieldB = fbm(rotate2d(-0.81) * silk * 0.91 - crossDirection * t * 0.61 + 5.4);
float fieldC = fbm(rotate2d(1.17) * silk * 1.16 + vec2(t * 0.37, -t * 0.29) + 9.7);
float softness = 0.08;
float veilA = smoothstep(0.28 - softness, 0.76 + softness, fieldA + (warpB - 0.5) * 0.28);
float veilB = smoothstep(0.34 - softness, 0.82 + softness, fieldB + (warpC - 0.5) * 0.24);
float veilC = smoothstep(0.42 - softness, 0.86 + softness, fieldC + (fieldA - 0.5) * 0.18);
float folded = 0.5 + 0.5 * sin(silk.y * 2.7 + silk.x * 0.72 + warpA * 3.1 - warpB * 1.9 + t * 0.47);
float silkFold = smoothstep(0.18, 0.92, folded) * smoothstep(0.12, 0.94, fieldB);
vec3 color = mix(COLOR_0, COLOR_1, clamp(0.22 + veilA * 0.62, 0.0, 1.0));
color = mix(color, COLOR_2, veilB * 0.58);
color = mix(color, COLOR_3, veilC * 0.42);
color += COLOR_4 * silkFold * 0.13;
vec2 lightCenter = vec2(0.5 + sin(t * 0.296 + 1.4) * 0.24, 0.48 + cos(t * 0.232 - 0.8) * 0.18);
vec2 lightDelta = rotate2d(0.42 + warpA * 0.22) * (uv - lightCenter);
lightDelta *= vec2(0.74, 1.32);
float bloom = exp(-dot(lightDelta, lightDelta) / (0.34 * 0.34));
bloom *= 0.76 + fieldC * 0.24;
color += mix(COLOR_3, COLOR_4, 0.58) * bloom * 0.22 * 0.8;
vec2 ambientDelta = (uv - vec2(0.52, 0.47)) * vec2(0.72, 1.0);
float ambient = exp(-dot(ambientDelta, ambientDelta) / 0.34);
color += mix(COLOR_2, COLOR_4, 0.5) * ambient * 0.12 * 0.7;
float haze = fbm(p * 2.6 + vec2(-t * 0.18, t * 0.14));
color += (haze - 0.5) * 0.16 * 0.16;
float vignetteMask = smoothstep(0.18, 1.08, length((uv - 0.5) * vec2(1.0, 0.86)));
color *= 1.0 - vignetteMask * 0.52 * 0.55;
float grain = hash(gl_FragCoord.xy + floor(u_time * 12.0) * 17.0) - 0.5;
color += grain * 0.06 * 0.16;
color = (color - 0.5) * 1.04 + 0.5;
gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}
`;
function init() {
var gl = canvas.getContext('webgl', { alpha: false, antialias: false });
if (!gl) {
return;
}
function compile(type, source) {
var shader = gl.createShader(type);
gl.shaderSource(shader, source);
gl.compileShader(shader);
return gl.getShaderParameter(shader, gl.COMPILE_STATUS) ? shader : null;
}
var vertex = compile(gl.VERTEX_SHADER, VERTEX);
var fragment = compile(gl.FRAGMENT_SHADER, FRAGMENT);
if (!vertex || !fragment) {
return;
}
var program = gl.createProgram();
gl.attachShader(program, vertex);
gl.attachShader(program, fragment);
gl.linkProgram(program);
if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
return;
}
gl.useProgram(program);
var position = gl.getAttribLocation(program, 'position');
gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
gl.enableVertexAttribArray(position);
gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);
var uRes = gl.getUniformLocation(program, 'u_res');
var uPointer = gl.getUniformLocation(program, 'u_pointer');
var uTime = gl.getUniformLocation(program, 'u_time');
var calm = window.matchMedia('(prefers-reduced-motion: reduce)');
var STILL_TIME = 7.25;
var pointer = { x: 0.5, y: 0.5 };
var target = { x: 0.5, y: 0.5 };
var raf = 0;
var last = 0;
var elapsed = 0;
var visible = false;
var lost = false;
function draw() {
pointer.x += (target.x - pointer.x) * 0.035;
pointer.y += (target.y - pointer.y) * 0.035;
gl.uniform2f(uPointer, pointer.x, pointer.y);
gl.uniform1f(uTime, calm.matches ? STILL_TIME : elapsed);
gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
}
function resize() {
var box = panel.getBoundingClientRect();
var scale = window.matchMedia('(pointer: coarse)').matches ? 0.5 : 0.75;
canvas.width = Math.max(1, Math.floor(box.width * scale));
canvas.height = Math.max(1, Math.floor(box.height * scale));
gl.viewport(0, 0, canvas.width, canvas.height);
gl.uniform2f(uRes, canvas.width, canvas.height);
if (!lost) {
draw();
}
}
function frame(now) {
elapsed += Math.min(now - last, 50) / 1000;
last = now;
draw();
raf = window.requestAnimationFrame(frame);
}
function sync() {
var run = visible && !document.hidden && !calm.matches && !lost;
if (run && !raf) {
last = window.performance.now();
raf = window.requestAnimationFrame(frame);
} else if (!run && raf) {
window.cancelAnimationFrame(raf);
raf = 0;
}
}
resize();
canvas.classList.add('is-ready');
panel.addEventListener('pointermove', function (event) {
if (calm.matches) {
return;
}
var box = panel.getBoundingClientRect();
target.x = Math.min(1, Math.max(0, (event.clientX - box.left) / box.width));
target.y = Math.min(1, Math.max(0, 1 - (event.clientY - box.top) / box.height));
}, { passive: true });
panel.addEventListener('pointerleave', function () {
target.x = 0.5;
target.y = 0.5;
});
if ('ResizeObserver' in window) {
new ResizeObserver(resize).observe(panel);
}
if ('IntersectionObserver' in window) {
new IntersectionObserver(function (entries) {
visible = entries[0].isIntersecting;
sync();
}).observe(panel);
} else {
visible = true;
sync();
}
document.addEventListener('visibilitychange', sync);
calm.addEventListener('change', function () {
sync();
draw();
});
canvas.addEventListener('webglcontextlost', function (event) {
event.preventDefault();
lost = true;
sync();
canvas.classList.remove('is-ready');
});
}
if ('IntersectionObserver' in window) {
var waiting = new IntersectionObserver(function (entries) {
if (entries[0].isIntersecting) {
waiting.disconnect();
init();
}
}, { rootMargin: '300px 0px' });
waiting.observe(panel);
} else {
init();
}
})();
